export type Disciplina2027 = "biologia" | "quimica" | "redacao";

export interface CriterioDsea {
  descricao: string;
  pontos: number;
  palavrasChave?: string[];
}

export interface Questao2027 {
  id: string;
  semanaId: string;
  disciplina: Disciplina2027;
  tema: string;
  apoio: string;
  comando: string;
  padraoDsea: string;
  dicaTutor?: string;
  criterios: CriterioDsea[];
  pontuacaoMaxima: number; // 2.0 para Biologia/Química, 20.0 para Redação
}

export interface SemanaSimulado {
  id: string;
  numero: number;
  titulo: string;
  periodo: string;
  focoBio: string;
  focoQui: string;
  temaRedacao: string;
  biologia: Questao2027[];
  quimica: Questao2027[];
  redacao: Questao2027[];
}

const criteriosCiencia = (
  identificacao: string,
  mecanismo: string,
  palavrasId?: string[],
  palavrasMec?: string[],
): CriterioDsea[] => [
  {
    descricao: identificacao,
    pontos: 0.5,
    palavrasChave: palavrasId,
  },
  {
    descricao: "Localizar e articular corretamente a estrutura, etapa ou relação causal solicitada",
    pontos: 0.5,
  },
  {
    descricao: mecanismo,
    pontos: 1.0,
    palavrasChave: palavrasMec,
  },
];

type LinhaCiencia = [string, string, string, string, string, string, string, string?];

function montarQuestoes(
  semanaId: string,
  disciplina: "biologia" | "quimica",
  linhas: LinhaCiencia[],
): Questao2027[] {
  return linhas.map(([id, tema, apoio, comando, padraoDsea, identificacao, mecanismo, dicaTutor]) => ({
    id,
    semanaId,
    disciplina,
    tema,
    apoio,
    comando,
    padraoDsea,
    dicaTutor:
      dicaTutor ||
      "Construa uma cadeia causal completa: cite o fator inicial, o mecanismo intermediário e a consequência fisiológica ou química solicitada no comando.",
    criterios: criteriosCiencia(identificacao, mecanismo),
    pontuacaoMaxima: 2.0,
  }));
}

function criarRedacaoSemana(
  id: string,
  semanaId: string,
  tema: string,
  apoio: string,
  comando: string,
  padraoDsea: string,
  dicaTutor: string,
): Questao2027 {
  return {
    id,
    semanaId,
    disciplina: "redacao",
    tema,
    apoio,
    comando,
    padraoDsea,
    dicaTutor,
    criterios: [
      { descricao: "Tese clara e atendimento integral ao recorte temático proposto", pontos: 4.0 },
      { descricao: "Articulação crítica com a obra 'O bem-amado' (Dias Gomes) sem mero resumo de enredo", pontos: 4.0 },
      { descricao: "Consistência argumentativa, repertório sociopolítico e análise crítica", pontos: 4.0 },
      { descricao: "Coesão referencial/sequencial, progressão lógica e estrutura dissertativa (20–30 linhas)", pontos: 4.0 },
      { descricao: "Domínio da norma-padrão da língua portuguesa e precisão vocabular", pontos: 4.0 },
    ],
    pontuacaoMaxima: 20.0,
  };
}

